Method: fr.baretto.ollamassist.chat.rag.DocumentIngestFactory#create
Signature: public static EmbeddingStoreIngestor create(EmbeddingStore<TextSegment> store, Project project)
Body: {
    ClassLoader originalClassLoader = Thread.currentThread().getContextClassLoader();
    Thread.currentThread().setContextClassLoader(DocumentIngestFactory.class.getClassLoader());
    try {
        EmbeddingModel embeddingModel = createEmbeddingModel();
        return EmbeddingStoreIngestor.builder().embeddingStore(store).embeddingModel(embeddingModel).documentSplitter(new CodeAwareDocumentSplitter(project)).build();
    } finally {
        Thread.currentThread().setContextClassLoader(originalClassLoader);
    }
}


