Signature: public static EmbeddingModelCheckResult localFailedWithFallback(boolean fallbackAvailable)
Body: {
    if (fallbackAvailable) {
        return new EmbeddingModelCheckResult(Status.LOCAL_FAILED_FALLBACK_OK, "Local model unavailable (using Ollama fallback)", "Using nomic-embed-text as fallback");
    } else {
        return new EmbeddingModelCheckResult(Status.LOCAL_FAILED_NO_FALLBACK, "Local model unavailable", "Please run: ollama pull nomic-embed-text");
    }
}


