Method: fr.baretto.ollamassist.completion.SuggestionCache#generateCacheKey
Doc: * Generates a cache key based on editor state and context.
     * Takes into account file content hash, cursor position, and surrounding context.
Signature: public String generateCacheKey(@NotNull Editor editor, @Nullable String context)
Body: {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        // Access editor data safely with ReadAction
        String keyData = com.intellij.openapi.application.ApplicationManager.getApplication().runReadAction((com.intellij.openapi.util.Computable<String>) () -> {
            // Include file modification timestamp for cache invalidation
            long modificationStamp = editor.getDocument().getModificationStamp();
            // Include cursor position context (line number and position in line)
            int offset = editor.getCaretModel().getOffset();
            int lineNumber = editor.getDocument().getLineNumber(offset);
            int columnNumber = offset - editor.getDocument().getLineStartOffset(lineNumber);
            // Create composite key
            String safeContext = context != null ? context : "";
            String contextPart = safeContext.length() > 200 ? safeContext.substring(safeContext.length() - 200) : safeContext;
            return String.format("mod:%d|line:%d|col:%d|ctx:%s", modificationStamp, lineNumber, columnNumber, contextPart);
        });
        byte[] hash = md.digest(keyData.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        // Use first 16 characters
        return hexString.toString().substring(0, 16);
    } catch (Exception e) {
        log.warn("Failed to generate cache key, using fallback", e);
        // Use context only for consistent fallback keys (no timestamp)
        return String.valueOf((context != null ? context : "").hashCode());
    }
}


Method: fr.baretto.ollamassist.completion.EnhancedCompletionService#handleCompletionWithCache
Doc: * Handles completion with caching layer.
Signature: private void handleCompletionWithCache(@NotNull Editor editor, @NotNull ProgressIndicator indicator)
Body: {
    log.debug("handleCompletionWithCache() starting");
    indicator.setText("Building context...");
    // Build context for cache key generation and completion
    log.debug("About to call contextProvider.buildCompletionContextAsync()");
    CompletableFuture<CompletionContext> contextFuture = contextProvider.buildCompletionContextAsync(editor);
    log.debug("contextFuture created, setting up thenAccept callback");
    contextFuture.thenAccept(completionContext -> {
        log.debug("contextFuture.thenAccept() callback executing");
        if (indicator.isCanceled()) {
            log.debug("Indicator was cancelled, returning early");
            return;
        }
        log.debug("About to generate cache key");
        // Generate cache key (generateCacheKey handles ReadAction internally)
        String cacheKey = cache.generateCacheKey(editor, completionContext.getImmediateContext());
        log.debug("Cache key generated: {}", cacheKey.substring(0, Math.min(8, cacheKey.length())));
        // Check cache first
        log.debug("Checking cache for key");
        String cachedSuggestion = cache.get(cacheKey);
        if (cachedSuggestion != null) {
            log.debug("Cache HIT! Using cached suggestion");
            log.info("✅ Using cached suggestion: '{}'", cachedSuggestion.substring(0, Math.min(50, cachedSuggestion.length())));
            ApplicationManager.getApplication().invokeLater(() -> {
                if (!indicator.isCanceled()) {
                    int caretOffset = ApplicationManager.getApplication().runReadAction((Computable<Integer>) () -> editor.getCaretModel().getOffset());
                    suggestionManager.showSuggestion(editor, caretOffset, cachedSuggestion);
                    attachActionHandler(editor);
                }
            });
            return;
        } else {
            log.debug("Cache MISS for key");
            log.info("❌ Cache miss for key: {}", cacheKey.substring(0, Math.min(8, cacheKey.length())));
        }
        // Generate new suggestion
        log.debug("About to call generateNewSuggestion()");
        generateNewSuggestion(editor, completionContext, cacheKey, indicator);
        log.debug("generateNewSuggestion() called");
    }).exceptionally(throwable -> {
        log.warn("Context building failed", throwable);
        indicator.setText("Context failed, using basic mode...");
        generateBasicSuggestion(editor, indicator);
        return null;
    });
}


