        new SecretPattern("AWS access key",
            Pattern.compile("(?i)(AKIA|ASIA|AROA|AIPA|ANPA|ANVA|APKA)[0-9A-Z]{16}")),
        // AWS secret key — all common naming variants (underscore, camelCase, uppercase)
