            Pattern.compile("rk_(live|test)_[0-9a-zA-Z]{24,}")),
        // Twilio Account SID + Auth Token (Auth Token is 32 hex chars)
        new SecretPattern("Twilio credentials",
            Pattern.compile("AC[a-f0-9]{32}|SK[a-f0-9]{32}")),
