Body: {
    if (isModified()) {
        // Validate prompts before saving
        if (!configurationPanel.validatePrompts()) {
            return;
        }
        boolean needIndexation = needIndexation();
        boolean embeddingModelChanged = embeddingModelChanged();
        // Save to OllamaSettings
