        ollamaSettings.setChatOllamaUrl(configurationPanel.getChatOllamaUrl());
        ollamaSettings.setCompletionOllamaUrl(configurationPanel.getCompletionOllamaUrl());
        ollamaSettings.setEmbeddingOllamaUrl(configurationPanel.getEmbeddingOllamaUrl());
        ollamaSettings.setChatModelName(configurationPanel.getChatModel());
        ollamaSettings.setCompletionModelName(configurationPanel.getCompletionModel());
        ollamaSettings.setEmbeddingModelName(configurationPanel.getEmbeddingModel());
        ollamaSettings.setUsername(configurationPanel.getUsername());
        ollamaSettings.setPassword(configurationPanel.getPassword());
        ollamaSettings.setAuthMode(configurationPanel.getAuthMode());
        ollamaSettings.setApiKey(configurationPanel.getApiKey());
        ollamaSettings.setTimeout(configurationPanel.getTimeout());
        // Save to RAGSettings
        RAGSettings ragSettings = RAGSettings.getInstance();
        ragSettings.setSources(configurationPanel.getSources());
        ragSettings.setIndexationSize(configurationPanel.getMaxDocuments());
        // Save to ActionsSettings
        ActionsSettings actionsSettings = ActionsSettings.getInstance();
        actionsSettings.setAutoApproveFileCreation(configurationPanel.isAutoApproveFileCreation());
        actionsSettings.setToolsEnabled(configurationPanel.isToolsEnabled());
        actionsSettings.setCodeCompletionEnabled(configurationPanel.isCodeCompletionEnabled());
        // Save to PromptSettings
        PromptSettings promptSettings = PromptSettings.getInstance();
        promptSettings.setChatSystemPrompt(configurationPanel.getChatSystemPrompt());
        promptSettings.setRefactorUserPrompt(configurationPanel.getRefactorUserPrompt());
        // Save agent settings
        ollamaSettings.setAgentPlanTimeoutSeconds(configurationPanel.getAgentPlanTimeoutSeconds());
        ollamaSettings.setRunCommandTimeoutSeconds(configurationPanel.getRunCommandTimeoutSeconds());
        ollamaSettings.setApprovalTimeoutMinutes(configurationPanel.getApprovalTimeoutMinutes());
        ollamaSettings.setAgentToolTimeoutSeconds(configurationPanel.getAgentToolTimeoutSeconds());
        ollamaSettings.setAgentGlobalTimeoutMinutes(configurationPanel.getAgentGlobalTimeoutMinutes());
        ollamaSettings.setAgentParanoidMode(configurationPanel.isAgentParanoidMode());
        // Apply UI settings
        configurationPanel.applyUISettings();
        ApplicationManager.getApplication().getMessageBus().syncPublisher(ModelListener.TOPIC).reloadModel();
        if (embeddingModelChanged) {
            configurationPanel.notifyEmbeddingModelChanged();
            return;
        }
        if (needIndexation) {
            configurationPanel.triggerClearLocalStorage();
        }
    }
}


Method: fr.baretto.ollamassist.agent.PromptSanitizer#stripControlChars
Signature: private static String stripControlChars(String s)
Body: {
    // Remove null bytes, BOM, and other non-printable ASCII control chars
    // but keep \n, \r, \t which are legitimate in code
    s = s.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]", "");
    // Strip Unicode bidirectional control characters (RTLO, LRO, PDF, etc.) and
    // zero-width characters (ZWSP, BOM). These are used in bidi prompt injection
    // attacks where the display order of text differs from its byte order, making
    // injected instructions visually invisible or disguised in the IDE.
    s = s.replaceAll("[\\u200B\\u200F\\u202A-\\u202E\\u2066-\\u2069\\uFEFF]", "");
    return s;
}


