Method: fr.baretto.ollamassist.completion.SuggestionActionHandler#doExecute
Signature: protected void doExecute(@NotNull Editor editor, @Nullable Caret caret, DataContext dataContext)
Body: {
    log.debug("SuggestionActionHandler.doExecute() called");
    // This handler is installed on the IDE-wide Enter action, so it must stand down as
    // soon as the user switches inline completion off — including in editors and sessions
    // where it was installed before the setting changed.
    if (!isCodeCompletionEnabled()) {
        delegate(editor, caret, dataContext);
        return;
    }
    // Check if we have active suggestions
    if (suggestionManager.hasSuggestions()) {
        log.debug("Has suggestions - inserting current suggestion");
        suggestionManager.insertCurrentSuggestion(editor);
        return;
    }
    log.debug("No suggestions - delegating to original handler");
    delegate(editor, caret, dataContext);
}


Method: fr.baretto.ollamassist.chat.rag.DocumentIndexingPipeline#handleCorruption
Signature: public void handleCorruption()
Body: {
    processingLock.lock();
    try {
        log.warn("Index corruption detected - Recreating index...");
        embeddingStore.recreateIndex();
        ingestor = DocumentIngestFactory.create(embeddingStore, project);
        log.info("Index recreated - Resuming operations");
    } catch (Exception ex) {
        log.error("Critical error during index recovery", ex);
        close();
    } finally {
        processingLock.unlock();
    }
}


